"use strict";
const STORAGE_KEY="tlc-storyworks-prototype-lost-woods";
const $=id=>document.getElementById(id);
const els={sceneLabel:$("scene-label"),sceneText:$("scene-text"),encounterLabel:$("encounter-label"),title:$("encounter-title"),body:$("encounter-body"),controls:$("challenge-controls"),progressText:$("progress-text"),progressCount:$("progress-count"),progressFill:$("progress-fill"),progressBar:document.querySelector(".progress-track"),discoveries:$("discovery-list"),discoveryCount:$("discovery-count"),words:$("words"),choices:$("choices-count"),start:$("start-button"),reset:$("reset-button"),status:$("status")};
const LABELS={litLantern:"Lit the lantern",helpedFox:"Helped the fox",ignoredFox:"Left the fox behind",foxGift:"Received a gift from the fox",visitedCreek:"Chose the creek path",visitedLanternPath:"Chose the lantern path",foundCottage:"Found the cottage",foundKey:"Found the iron key",readJournal:"Read the cottage journal",helpedStranger:"Helped the stranger",rememberedPath:"Recognized a familiar path",foundMap:"Found the changing map",foundName:"Found a name in the tree",acceptedFeather:"Accepted the blue feather",sawWatcher:"Faced the Watcher",rememberedForest:"Received a forest memory",metForestKeeper:"Met the Keeper of Paths",answeredForest:"Answered the forest's question",openedDoor:"Opened the door between trees",leftOffering:"Left an offering",foundHollow:"Explored the hollow",foundBackpack:"Found the backpack",metDouble:"Met your double",heardCrow:"Heard the crow's answer",followedDeer:"Followed the white deer",metRabbit:"Met the talking rabbit",crossedCreek:"Crossed the strange creek",foundCamp:"Found the abandoned camp",sawSecondMoon:"Saw the second moon",heardVoice:"Heard the voice underground",tookShortcut:"Chose the shortcut",metChild:"Met the child",sawFoxAgain:"Saw the fox again",foxGuided:"The fox guided you",metKeeper:"Met the Lantern Keeper",openedCupboard:"Opened the locked cupboard"};
const STEPS=[
{kind:"challenge",label:"The Forest Edge",title:"The road ends sooner than the map promised.",scene:"The road ends sooner than the map promised. Beyond the broken sign, the forest begins. Someone has carved words into the wood: IF YOU ARE LOST, DO NOT FOLLOW THE PATH THAT LOOKS FAMILIAR.",prompt:"Write at least 250 words about why your protagonist enters the woods anyway. What are they looking for, leaving behind, or hoping not to find?",min:250},
{kind:"choice",label:"The First Fork",title:"Two paths, neither entirely trustworthy.",scene:"The path divides around an ancient oak. To the left, tiny lanterns hang from the branches, each glowing with a soft gold light. To the right, you hear running water, though the map shows no creek nearby.",prompt:"Choose the path your protagonist takes.",choices:[{label:"Take the Lantern Path",flag:"visitedLanternPath",next:"lantern"},{label:"Follow the Creek",flag:"visitedCreek",next:"creek"}]},
{kind:"path",label:"The First Path",title:"Your first discovery",scene:"",prompt:""},
{kind:"challenge",label:"The First Sign",title:"The signs disagree.",scene:"A wooden sign points toward HOME. Another points toward the place your protagonist most wants to find. A third points toward a place they have never heard of. All three have fresh footprints beneath them.",prompt:"Write at least 300 words about which sign your protagonist wants to believe, which they actually follow, and what the choice costs them.",min:300},
{kind:"challenge",label:"The First Night",title:"The forest grows dark.",scene:"The light drains from the sky, but the woods do not become fully dark. Pale shapes glow beneath the leaves. Somewhere nearby, something is arranging small stones in a circle.",prompt:"Write at least 350 words about where your protagonist makes shelter for the night—and what visits while they are trying to rest.",min:350},
{kind:"random",label:"The Deep Woods",title:"A discovery in the deep woods",scene:"The path narrows. The trees grow close enough that their branches knit together overhead. The forest seems to be waiting for you to notice something.",count:1},
{kind:"random",label:"The Deep Woods",title:"Another turn in the woods",scene:"A sound carries through the trees: a laugh, a footstep, or perhaps the creak of a door. The forest has more than one secret left.",count:1},
{kind:"cottage",label:"The Cottage",title:"A cottage where no cottage should be.",scene:"A little cottage stands in a pocket of warm light. Smoke rises from the chimney, but the windows are dark. A handwritten sign on the door says: COME IN IF YOU HAVE BROUGHT SOMETHING WITH YOU.",prompt:"Choose how your protagonist approaches the cottage.",choices:[{label:"Go inside and investigate",flag:"foundCottage",next:"inside"},{label:"Leave something at the door and move on",flag:"leftOffering",next:"outside"},{label:"Keep walking",next:"away"}]},
{kind:"random",label:"Beyond the Cottage",title:"The woods answer back",scene:"The trees shift behind you. The way you came is no longer where you left it. Something you've discovered—or failed to discover—seems to be guiding the next turn.",count:1},
{kind:"fixed",label:"The Old Clearing",title:"YOU HAVE BEEN HERE BEFORE.",scene:"An enormous tree rises from the middle of a clearing. Its roots curl around a stone marked with a single sentence: YOU HAVE BEEN HERE BEFORE.",prompt:"Write at least 400 words about the memory the tree gives your protagonist—or the memory it refuses to return. Let the answer change what they believe about this journey.",min:400,flag:"rememberedForest"},
{kind:"conditional",label:"The Watcher",title:"Something watches from the tree line.",scene:"The forest goes quiet. Between the trunks, something watches you without moving. You cannot tell whether it is keeping you here or keeping something else away.",prompt:"Write at least 400 words about what your protagonist does when they realize the Watcher has been nearby for a long time.",min:400,flag:"sawWatcher"},
{kind:"keeper",label:"The Keeper of Paths",title:"The forest has been talking about you.",scene:"A figure in a coat stitched with leaves waits at a crossroads. “The forest has been telling me about you,” they say. “I would like to hear your version.”",prompt:"Write at least 450 words about how the Keeper reacts to your protagonist's choices and how your protagonist explains them.",min:450,flag:"metForestKeeper"},
{kind:"challenge",label:"The Forest Heart",title:"The Forest's Hidden Heart",scene:"At the forest's heart, a ring of pale mushrooms surrounds a dark pool. Its surface pulses with reflected light, though the sky above is hidden by leaves. From somewhere below the water comes a sound like a distant heartbeat. A voice asks what your protagonist believes the forest has been protecting.",prompt:"Write at least 500 words revealing what lies beneath the pool—or what the forest has been keeping safe all this time. It can be a creature, a memory, a person, a promise, or something your protagonist cannot name.",min:500,flag:"answeredForest"},
{kind:"challenge",label:"The Forest's Question",title:"Why did you come here?",scene:"The trees lean inward. Every path you've taken seems to meet beneath this canopy. The voice asks again, more gently this time: “Why did you come here?”",prompt:"Write at least 500 words about the reason your protagonist came into the woods—and the reason they can finally admit to themselves.",min:500},
{kind:"ending",label:"The Final Path",title:"The forest offers you a way forward.",scene:"Three paths open beneath the oldest tree. One leads toward a distant road. One descends into a warm green glow. The last curves back into the woods, toward a place your protagonist now recognizes.",prompt:"Choose how your protagonist's journey ends.",choices:[{label:"Leave the forest",ending:"leave"},{label:"Stay and become a Keeper",ending:"stay"},{label:"Leave, but promise to return",ending:"return"}]}
];
let state;
function freshState(){return{active:false,complete:false,index:0,flags:{},choices:0,words:0,used:[],path:null,selected:null,ending:null}}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch{}}
function load(){try{const v=JSON.parse(localStorage.getItem(STORAGE_KEY));return v&&typeof v==="object"?{...freshState(),...v,flags:{...(v.flags||{})}}:freshState()}catch{return freshState()}}
state=load();
function status(s){els.status.textContent=s}
function addFlag(flag){if(flag)state.flags[flag]=true}
function has(flag){return !!state.flags[flag]}
function addParagraphs(el,text){el.replaceChildren();String(text||"").split("\n\n").forEach(t=>{const p=document.createElement("p");p.textContent=t;el.appendChild(p)})}
function button(label,fn,cls="primary"){const b=document.createElement("button");b.type="button";b.className=cls;b.textContent=label;b.addEventListener("click",fn);return b}
function controlButton(label,fn){els.controls.appendChild(button(label,fn))}
function makeChallenge(prompt,min,onComplete){const p=document.createElement("p");p.className="prompt-text";p.textContent=prompt;els.body.appendChild(p);const label=document.createElement("label");label.htmlFor="word-count-input";label.textContent="Words written";const input=document.createElement("input");input.id="word-count-input";input.type="number";input.min="0";input.step="1";input.inputMode="numeric";input.placeholder="e.g. 350";input.setAttribute("aria-describedby","minimum-words");const hint=document.createElement("span");hint.id="minimum-words";hint.className="muted";hint.textContent="Suggested minimum: "+min+" words (you can continue when ready).";els.controls.append(label,input,hint);controlButton("Complete challenge",()=>{const n=Math.max(0,Number.parseInt(input.value,10)||0);state.words+=n;onComplete();state.index++;state.selected=null;save();render();status("Challenge complete. The forest remembers.");});}
function eligibleEncounters(){return LOST_WOODS.encounters.filter(e=>!state.used.includes(e.id)&&(!e.requires||e.requires.every(has)))}
function renderEncounter(enc){state.used.push(enc.id);addParagraphs(els.sceneText,enc.body);els.encounterLabel.textContent="Forest encounter · "+enc.tags.join(" · ");els.title.textContent=enc.title;els.body.replaceChildren();makeChallenge(enc.prompt,enc.min,()=>{(enc.success||[]).forEach(x=>addFlag(x.flag));});}
function pickRandom(){const available=eligibleEncounters();if(!available.length)return null;const e=available[Math.floor(Math.random()*available.length)];return e}
function renderChoice(step){const p=document.createElement("p");p.className="prompt-text";p.textContent=step.prompt;els.body.appendChild(p);const group=document.createElement("div");group.className="choice-group";step.choices.forEach(c=>group.appendChild(button(c.label,()=>{state.choices++;if(c.flag)addFlag(c.flag);if(step.kind==="choice"){state.path=c.next;if(c.next==="lantern"){state.selected="lantern"}else if(c.next==="creek"){state.selected="creek"}}if(step.kind==="cottage"){if(c.next==="inside"){addFlag("foundCottage");state.selected="inside"}else if(c.next==="outside"){state.selected="outside"}else state.selected="away"}if(step.kind==="ending"){state.ending=c.ending;finishEnding();return}save();if(step.kind==="choice"||step.kind==="cottage"){state.index++;render();status("Choice made. The woods will remember.");}else render();})));els.controls.appendChild(group)}
function finishPath(){const type=state.selected;els.encounterLabel.textContent="Your chosen path";if(type==="lantern"){els.title.textContent="The Lantern Path";addParagraphs(els.sceneText,"Tiny lanterns hang from the branches. One is cold, one is cracked, and one burns with a flame that gives no heat. The unbroken lantern lifts from its hook when your protagonist approaches.");els.body.replaceChildren();makeChallenge("Write at least 300 words about who left the lantern here, why they wanted it found, and what your protagonist notices when they light it.",300,()=>addFlag("litLantern"));}else if(type==="creek"){els.title.textContent="The Creek Path";addParagraphs(els.sceneText,"The sound leads to a narrow creek flowing uphill. A small fox is caught in a tangle of thorny roots on the bank. It watches your protagonist with bright, wary eyes.");els.body.replaceChildren();const p=document.createElement("p");p.className="prompt-text";p.textContent="What does your protagonist do?";els.body.appendChild(p);const g=document.createElement("div");g.className="choice-group";[{label:"Help the fox",flag:"helpedFox",prompt:"Write at least 300 words about freeing the fox, what it does once it is free, and why your protagonist decides to help."},{label:"Keep walking",flag:"ignoredFox",prompt:"Write at least 300 words about why your protagonist leaves the fox behind and what they notice as they walk away."},{label:"Leave a gift, then go",flag:"foxGift",prompt:"Write at least 300 words about what your protagonist leaves for the fox and what passes between them without words."}].forEach(c=>g.appendChild(button(c.label,()=>{state.choices++;addFlag(c.flag);const pr=els.body.querySelector(".prompt-text");pr.textContent=c.prompt;g.remove();const old=els.controls.querySelector("button");if(old)old.remove();makeChallenge(c.prompt,300,()=>{});save();})));els.controls.appendChild(g)}}
function renderCottage(){if(!state.selected){els.body.replaceChildren();const p=document.createElement("p");p.className="prompt-text";p.textContent="Choose how your protagonist approaches the cottage.";els.body.appendChild(p);const g=document.createElement("div");g.className="choice-group";[{label:"Go inside and investigate",next:"inside"},{label:"Leave something at the door",next:"outside"},{label:"Keep walking",next:"away"}].forEach(c=>g.appendChild(button(c.label,()=>{state.choices++;state.selected=c.next;if(c.next==="inside")addFlag("foundCottage");if(c.next==="outside")addFlag("leftOffering");save();renderCottage();updateStats();renderDiscoveries();})));els.controls.appendChild(g)}else if(state.selected==="inside"&&!state.cottageChoice){addParagraphs(els.sceneText,"Inside, the cottage smells of rain and cinnamon. A journal lies open on the table beside a map of the forest. A small iron key hangs from a nail above the cold fireplace.");els.body.replaceChildren();const p=document.createElement("p");p.className="prompt-text";p.textContent="Choose what your protagonist investigates.";els.body.appendChild(p);const g=document.createElement("div");g.className="choice-group";[{label:"Read the journal",flag:"readJournal",text:"Write at least 350 words about the journal's final entry and the person who wrote it.",min:350},{label:"Take the iron key",flag:"foundKey",text:"Write at least 300 words about why your protagonist takes the key and what it seems to unlock.",min:300},{label:"Study the map",flag:"foundMap",text:"Write at least 350 words about the map's changing route and the place marked with a green dot.",min:350}].forEach(c=>g.appendChild(button(c.label,()=>{state.choices++;addFlag(c.flag);state.cottageChoice=c.flag;g.remove();makeChallenge(c.text,c.min,()=>{});save();updateStats();renderDiscoveries();})));els.controls.appendChild(g)}else if(state.selected==="outside"){addParagraphs(els.sceneText,"Your offering rests on the threshold. The door opens a finger's width, though nobody is visible inside. Something small and bright rolls onto the step.");els.body.replaceChildren();makeChallenge("Write at least 300 words about what your protagonist leaves, what the cottage gives in return, and why they don't go inside.",300,()=>{addFlag("leftOffering");addFlag("foundCottage")})}else if(state.selected==="away"){addParagraphs(els.sceneText,"The cottage light goes out behind you. A window opens, then closes. Whatever was waiting inside has decided not to follow.");els.body.replaceChildren();makeChallenge("Write at least 300 words about why your protagonist refuses the cottage's invitation and what they fear might be waiting there.",300,()=>{})}else{addParagraphs(els.sceneText,"Inside, the cottage is quiet. The forest seems to be waiting for you to finish your investigation.");makeChallenge("Write at least 300 words about what your protagonist discovers in the cottage.",300,()=>{})}}function conditionalWatcher(){let extra="";if(has("litLantern"))extra+=" Your lantern throws a circle of gold between you and the trees; something's eyes shine just beyond it.";if(has("helpedFox"))extra+=" The fox steps between you and the darkness, standing very still.";if(has("readJournal"))extra+=" You recognize the shape from a drawing in the cottage journal.";if(has("acceptedFeather"))extra+=" The blue feather in your pocket trembles as if caught in a wind you cannot feel.";if(!extra)extra=" You have no light, no guide, and no explanation for the feeling that the Watcher is waiting for you to speak first.";return extra}
function keeperScene(){let s="The Keeper listens without interrupting.";if(has("helpedFox"))s+=' “So you still remember how to be kind,” the Keeper says.';if(has("helpedStranger"))s+=' “You brought another lost thing closer to home,” the Keeper says.';if(has("foundKey"))s+=' Their gaze falls to the iron key. “You found a way to open something. That is not always the same as finding a way out.”';if(has("leftOffering"))s+=' “You understood that a place can ask for a gift,” they say.';if(has("tookShortcut"))s+=' “You chose the quick path. The forest has a long memory for shortcuts.”';if(!has("helpedFox")&&!has("helpedStranger")&&!has("foundKey")&&!has("leftOffering")&&!has("tookShortcut"))s+=' “You have been careful not to leave much behind,” the Keeper says. “I wonder if that was kindness or fear.”';return s}
function finishEnding(){state.complete=true;state.active=false;save();els.encounterLabel.textContent="Your ending";els.body.replaceChildren();let title,text,extra="";if(state.ending==="leave"){title="The Returned";text="The trees part, and the road appears. You step out of the forest carrying the story you made there.";if(has("litLantern"))extra+=" Your lantern burns all the way to the road's edge.";if(has("helpedFox"))extra+=" The fox watches until you are safely beyond the trees.";if(has("foundCottage"))extra+=" A warm light remains in the cottage window.";if(has("foundKey"))extra+=" The key is cool in your hand now. You no longer need it."}else if(state.ending==="stay"){title="The Keeper";text="The forest opens a small place for you beneath its branches. In time, travelers will find lights along the paths and a voice that knows how to guide them.";if(has("helpedFox"))extra+=" The fox curls beside your new doorstep.";if(has("litLantern"))extra+=" The lantern is the first light you hang for someone else."}else{title="The One Who Returns";text="You find the road and walk toward home. You do not promise the forest forever—only that you will come back when you can.";if(has("rememberedForest"))extra+=" The memory of the old tree stays clear, even after the road turns.";if(has("readJournal"))extra+=" You carry the journal's final sentence with you."}els.title.textContent=title;addParagraphs(els.sceneText,text+extra);const p=document.createElement("p");p.className="prompt-text";p.textContent="Write a final 300 words showing the last image of this journey—and the first hint of what happens next.";els.body.appendChild(p);const input=document.createElement("input");input.type="number";input.min="0";input.placeholder="Words written";input.setAttribute("aria-label","Final words written");els.controls.replaceChildren(input,button("Record ending",()=>{state.words+=Math.max(0,Number.parseInt(input.value,10)||0);save();updateStats();status("The Lost Woods is complete. The forest will remember this version of the story.");els.controls.replaceChildren(button("Play another route",reset,"secondary"));updateProgress();}, "primary"));els.start.textContent="Journey complete";els.start.disabled=true;updateStats();updateProgress()}
function render(){if(state.complete){finishEnding();return}if(!state.active){return}const step=STEPS[state.index];if(!step){finishEnding();return}els.sceneLabel.textContent=step.label;els.encounterLabel.textContent="Story beat "+(state.index+1);els.title.textContent=step.title;addParagraphs(els.sceneText,step.scene||"");els.body.replaceChildren();els.controls.replaceChildren();if(step.kind==="path"){finishPath()}else if(step.kind==="random"){const enc=pickRandom();if(enc)renderEncounter(enc);else{els.title.textContent="A Quiet Stretch of Woods";makeChallenge("Write at least 300 words about a quiet moment in the forest and what your protagonist realizes when nothing interrupts them.",300,()=>{})}}else if(step.kind==="cottage"){renderCottage()}else if(step.kind==="conditional"){addParagraphs(els.sceneText,step.scene+conditionalWatcher());makeChallenge(step.prompt,step.min,()=>addFlag(step.flag))}else if(step.kind==="keeper"){addParagraphs(els.sceneText,step.scene+" "+keeperScene());makeChallenge(step.prompt,step.min,()=>addFlag(step.flag))}else if(step.kind==="choice"||step.kind==="ending"){renderChoice(step)}else{makeChallenge(step.prompt,step.min,()=>{if(step.flag)addFlag(step.flag)})}updateStats();updateProgress();renderDiscoveries();save()}
function updateStats(){$("discovery-count").textContent=Object.keys(state.flags).filter(k=>state.flags[k]).length;els.words.textContent=state.words;els.choices.textContent=state.choices}
function updateProgress(){const total=STEPS.length;const done=state.complete?total:state.index;els.progressCount.textContent=done+" / "+total;els.progressFill.style.width=(done/total*100)+"%";els.progressBar.setAttribute("aria-valuemax",String(total));els.progressBar.setAttribute("aria-valuenow",String(done));els.progressText.textContent=state.complete?"Journey complete":state.active?(STEPS[state.index]?.label||"The forest remembers"):"The forest edge"}
function renderDiscoveries(){els.discoveries.replaceChildren();const found=Object.keys(state.flags).filter(k=>state.flags[k]);if(!found.length){const li=document.createElement("li");li.textContent="Nothing yet. The forest is watching.";els.discoveries.appendChild(li)}else found.forEach(k=>{const li=document.createElement("li");li.textContent=LABELS[k]||k;els.discoveries.appendChild(li)})}
function reset(){state=freshState();save();els.start.disabled=false;els.start.textContent="Enter the woods";els.sceneLabel.textContent="The Forest Edge";addParagraphs(els.sceneText,"The road ends sooner than the map promised. Beyond the broken sign, the forest begins. Someone has carved words into the wood: IF YOU ARE LOST, DO NOT FOLLOW THE PATH THAT LOOKS FAMILIAR.");els.encounterLabel.textContent="Your story begins";els.title.textContent="If you are lost, do not follow the familiar path.";els.body.replaceChildren();const p=document.createElement("p");p.textContent="Start your journey when you're ready.";els.body.appendChild(p);els.controls.replaceChildren();updateStats();updateProgress();renderDiscoveries();status("Crawl reset.")}
function start(){state=freshState();state.active=true;state.index=0;save();els.start.textContent="Journey in progress";render();status("You've entered the woods. Choose carefully; the forest remembers.");}
els.start.addEventListener("click",()=>{if(!state.active&&!state.complete)start()});
els.reset.addEventListener("click",reset);
if(state.active){els.start.textContent="Journey in progress";render()}else if(state.complete){finishEnding()}else{updateStats();updateProgress();renderDiscoveries();status("Ready when you are.")}
